export const INDIA_DISTRICTS_BY_STATE = INDIA_LOCATIONS.reduce((acc, entry) => {
  (acc[entry.state] ||= []).push(entry.district);
  return acc;
}, {});

// Search-typeahead aliases only - matching/normalization for the actual candidate
// search filter happens server-side (backend/src/services/search/searchUtils.js
// LOCATION_ALIASES, kept in sync with this list). This map never changes a
// candidate's stored/displayed location text.
export const INDIA_LOCATION_SEARCH_ALIASES = {
  bangalore: 'bengaluru',
  bombay: 'mumbai',
  gurgaon: 'gurugram',
  calcutta: 'kolkata',
  cochin: 'kochi',
  vizag: 'visakhapatnam',
  baroda: 'vadodara',
  trivandrum: 'thiruvananthapuram',
};

/**
 * Search across state names, district names, and the alias table. Returns
 * matches grouped by state so the tree can expand only the relevant branches.
 */
export function searchIndiaLocationTree(query) {
  const needle = String(query || '').trim().toLowerCase();
  if (!needle) {
    return INDIA_STATES.map((state) => ({ state, districts: INDIA_DISTRICTS_BY_STATE[state], stateMatched: false }));
  }

  const aliasTarget = INDIA_LOCATION_SEARCH_ALIASES[needle];

  return INDIA_STATES
    .map((state) => {
      const stateMatched = state.toLowerCase().includes(needle);
      const districts = (INDIA_DISTRICTS_BY_STATE[state] || []).filter((district) => {
        const normalized = district.toLowerCase();
        return normalized.includes(needle) || (aliasTarget && normalized.includes(aliasTarget));
      });
      return { state, districts: stateMatched ? INDIA_DISTRICTS_BY_STATE[state] : districts, stateMatched };
    })
    .filter((group) => group.stateMatched || group.districts.length);
}
